void rotate_argb_part(
    unsigned int *src, int width, int height, int from, int to,
     int angle, unsigned int color, unsigned int *dst)
{
	int x, y;

	int x_center = width / 2;
	int y_center = height / 2;

    dst = dst + from * width;

	for (y = from; y < to; y++) {
		for (x = 0; x < width; x++) {
			int y0 = y-y_center;
			int x0 = x-x_center;
			int x1 = (fcosdata[angle]*x0 - fsindata[angle]*y0)/1000;
			int y1 = (fsindata[angle]*x0 + fcosdata[angle]*y0)/1000;

			x1 += x_center;
			y1 += y_center;

			if (x1 < 0 || x1 >= width || y1 < 0 || y1 >= height)
				dst[x] = color;
			else
				dst[x] = src[y1*width + x1];
		}
		dst += width;
	}
}

void rotate_argb(unsigned int *src, int width, int height, int angle, unsigned int color, unsigned int *dst)
{
	rotate_argb_part(src, width, height, 0, height, angle, color, dst);
}

#include <pthread.h>
#include <assert.h>
#include <semaphore.h>
#include "message_queue.h"

struct rotate_data {
	unsigned int *src;
	int width;
	int height;
	int angle;
	unsigned int color;
	unsigned int *dst;
    sem_t sem;
};

static pthread_t m_thread;

static struct message_queue *m_queue;

void *rotate_bottom_thread_func(void *data)
{
	while (1) {
        struct message *msg = message_queue_receive(m_queue);
        struct rotate_data *r = (void *)msg->data;

        if (r == NULL)
            break;

        rotate_argb_part(r->src, r->width, r->height,
             r->height/2, r->height, r->angle, r->color, r->dst);
        sem_post(&r->sem);
    }

	return NULL;
}

void rotate_argb_j2(unsigned int *src, int width, int height, int angle, unsigned int color, unsigned int *dst)
{
	struct rotate_data r = {
		.src = src, .width = width, .height = height,
		.angle = angle, .color = color, .dst = dst,
	};
    sem_init(&r.sem, 0, 0);

    struct message msg;
    msg.data = (unsigned long) &r;
    message_queue_send(m_queue, &msg);

	rotate_argb_part(src, width, height, 0, height/2, angle, color, dst);
	sem_wait(&r.sem);
    sem_destroy(&r.sem);
}

void rotate_init(void)
{
    m_queue = message_queue_create(0, 0);
    assert(m_queue);

	int ret = pthread_create(&m_thread, NULL, rotate_bottom_thread_func, NULL);
	assert(!ret);
}

void rotate_destory(void)
{
    struct message msg;
    msg.data = 0;
    message_queue_send(m_queue, &msg);

    pthread_join(m_thread, NULL);
    message_queue_delete(m_queue);
}
